<?php $labels=['clothes'=>'Vetements','brands'=>'Marques','outfits'=>'Tenues','collections'=>'Collections','trips'=>'Voyages','categories'=>'Categories']; ?>
<section class="page-heading"><div><p class="eyebrow">VETEMENTS, TENUES, COLLECTIONS ET VOYAGES</p><h1>Recherche</h1><p class="subheading"><?= $query ? 'Resultats pour &laquo; '.e($query).' &raquo;' : 'Saisissez au moins deux caracteres dans la barre de recherche.' ?></p></div></section>
