<?php if($query && mb_strlen($query)>=2): $any=false; foreach($results as $type=>$rows): if($rows): $any=true; ?><section class="search-result-group"><h2><?= e($labels[$type]??$type) ?> <small><?= count($rows) ?></small></h2><?php foreach($rows as $row): $href=match($type){'clothes'=>url('clothes-show',['id'=>$row['id']]),'outfits'=>url('outfits-show',['id'=>$row['id']]),'collections'=>url('collection-show',['id'=>$row['id']]),'trips'=>url('trip-show',['id'=>$row['id']]),'categories'=>url('clothes',['label'=>$row['detail']]),default=>url('clothes',['q'=>$row['name']])}; ?><a class="search-result" href="<?= e($href) ?>"><b><?= e($row['name']) ?></b><span><?= e($row['detail']??'') ?></span><i>&rarr;</i></a><?php endforeach; ?></section><?php endif; endforeach; if(!$any): ?><div class="empty-state"><h3>Aucun resultat</h3><p>Essayez un autre terme de recherche.</p></div><?php endif; endif; ?>
